import{_ as t,o as a,c as s,N as n}from"./chunks/framework.11ad0a06.js";const u=JSON.parse('{"title":"Create a New Project","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/install.md","lastUpdated":1795525255000}'),l={name:"en/guide/install.md"};function o(r,e,p,i,c,d){return a(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="create-a-new-project" tabindex="-1">Create a New Project <a class="header-anchor" href="#create-a-new-project" aria-label="Permalink to &quot;Create a New Project&quot;">​</a></h1><h3 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h3><p><code>create-wujie</code> helps you scaffold starter demo projects quickly so you can get up and running with Wujie right away.</p><ul><li>Select one or more sub-apps when creating a project to develop and test with specific frameworks.</li><li>Choose routing modes (<code>hash</code> or <code>history</code>) for both the main app and sub-apps.</li></ul><p>More features, frameworks, and version templates will continue to be added to make onboarding with <code>wujie</code> even easier.</p><p>If you encounter any issues, please report them on <a href="https://github.com/wujie-micro/create-wujie/issues" target="_blank" rel="noreferrer">GitHub Issues</a>.</p><h3 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h3><p>Development environment requirements:</p><ul><li><a href="https://nodejs.org/en/" target="_blank" rel="noreferrer">Node.js</a> version <code>&lt; 18.0.0</code> (for the legacy starter templates)</li><li><a href="https://pnpm.io/" target="_blank" rel="noreferrer">pnpm</a> — starter templates are managed with <code>pnpm</code> + <a href="https://turborepo.org/docs/getting-started" target="_blank" rel="noreferrer">Turborepo</a></li></ul><p>If you need to switch Node.js versions in your local environment, use <a href="https://github.com/nvm-sh/nvm" target="_blank" rel="noreferrer">nvm</a> or <a href="https://github.com/Schniz/fnm" target="_blank" rel="noreferrer">fnm</a>.</p><p>Example using <code>nvm</code> to install and switch to Node.js 16 LTS:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#676E95;font-style:italic;"># Install the LTS version of Node.js 16</span></span>
<span class="line"><span style="color:#FFCB6B;">nvm</span><span style="color:#BABED8;"> </span><span style="color:#C3E88D;">install</span><span style="color:#BABED8;"> </span><span style="color:#F78C6C;">16</span><span style="color:#BABED8;"> </span><span style="color:#C3E88D;">--lts</span></span>
<span class="line"></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># Make the newly installed Node.js 16 the default version</span></span>
<span class="line"><span style="color:#FFCB6B;">nvm</span><span style="color:#BABED8;"> </span><span style="color:#C3E88D;">alias</span><span style="color:#BABED8;"> </span><span style="color:#C3E88D;">default</span><span style="color:#BABED8;"> </span><span style="color:#F78C6C;">16</span></span>
<span class="line"></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># Switch to the newly installed Node.js 16</span></span>
<span class="line"><span style="color:#FFCB6B;">nvm</span><span style="color:#BABED8;"> </span><span style="color:#C3E88D;">use</span><span style="color:#BABED8;"> </span><span style="color:#F78C6C;">16</span></span>
<span class="line"></span></code></pre></div><h3 id="install" tabindex="-1">Install <a class="header-anchor" href="#install" aria-label="Permalink to &quot;Install&quot;">​</a></h3><p>Open a terminal and run the following command:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#676E95;font-style:italic;"># Install wujie Cursor skill</span></span>
<span class="line"><span style="color:#FFCB6B;">npx</span><span style="color:#BABED8;"> </span><span style="color:#C3E88D;">skills</span><span style="color:#BABED8;"> </span><span style="color:#C3E88D;">add</span><span style="color:#BABED8;"> </span><span style="color:#C3E88D;">wujie-micro/wujie-skill</span></span>
<span class="line"></span></code></pre></div><h3 id="template-list" tabindex="-1">Template List <a class="header-anchor" href="#template-list" aria-label="Permalink to &quot;Template List&quot;">​</a></h3><ul><li>Main App Templates</li></ul><table><thead><tr><th>Main App Framework</th><th>Status</th></tr></thead><tbody><tr><td>Webpack + Vue 2</td><td>✅</td></tr><tr><td>Webpack + React 17</td><td>✅</td></tr><tr><td>Vite + Vue 3</td><td>🚧</td></tr></tbody></table><ul><li>Sub-app Templates</li></ul><table><thead><tr><th>Sub-app Framework</th><th>Status</th></tr></thead><tbody><tr><td>Vite + Vue 3</td><td>✅</td></tr><tr><td>Webpack + Vue 2</td><td>✅</td></tr><tr><td>Webpack + Vue 3</td><td>✅</td></tr><tr><td>Webpack + React 16</td><td>✅</td></tr><tr><td>Webpack + React 17</td><td>✅</td></tr><tr><td>Angular 12</td><td>✅</td></tr></tbody></table>`,20)])])}const m=t(l,[["render",o]]);export{u as __pageData,m as default};
